'use strict';
const conditions=[
{name:'Migraine',lines:['MIGRAINE'],note:'A migraine episode. Experiences vary and it may not be obvious to others.'},
{name:'IBS flare-up',lines:['IBS','FLARE-UP'],note:'An irritable bowel syndrome flare-up. Often not outwardly visible.'},
{name:'Acid reflux',lines:['ACID','REFLUX'],note:'An acid reflux episode. Often not outwardly visible.'},
{name:'Insomnia',lines:['INSOMNIA'],note:'Sleep disruption affecting the contestant’s day. Often not outwardly visible.'},
{name:'Tension headache',lines:['TENSION','HEADACHE'],note:'A tension headache. Often not outwardly visible.'},
{name:'Vertigo',lines:['VERTIGO'],note:'A vertigo episode. Symptoms may not be apparent to others.'},
{name:'Period pain',lines:['PERIOD','PAIN'],note:'Menstrual pain. Often not outwardly visible.'},
{name:'Anxiety flare-up',lines:['ANXIETY','FLARE-UP'],note:'An anxiety flare-up. Experiences vary and it may not be obvious to others.'}
];
const colours=['#ffcf40','#742ddb','#ff5bb6','#3d9fb1','#ffcf40','#742ddb','#ff5bb6','#3d9fb1'];
const $=id=>document.getElementById(id),canvas=$('wheel'),ctx=canvas.getContext('2d');
let angle=0,busy=false,selected=null,points=0,round=1,record={},audio=null,sound=false,gameNumber=1;
function draw(){const n=conditions.length,step=Math.PI*2/n;ctx.clearRect(0,0,760,760);ctx.save();ctx.translate(380,380);ctx.rotate(angle);for(let i=0;i<n;i++){const a=i*step-Math.PI/2;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,375,a,a+step);ctx.closePath();ctx.fillStyle=colours[i];ctx.fill();ctx.strokeStyle='#160d2e44';ctx.lineWidth=3;ctx.stroke();ctx.save();ctx.rotate(a+step/2);ctx.translate(248,0);ctx.rotate(Math.PI/2);ctx.fillStyle=i%4===1?'#fff8ee':'#160d2e';ctx.font='900 25px Arial';ctx.textAlign='center';conditions[i].lines.forEach((line,j)=>ctx.fillText(line,0,(j-(conditions[i].lines.length-1)/2)*30));ctx.restore();}ctx.restore();}
function tone(frequency,duration=.08){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=frequency;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.start();o.stop(audio.currentTime+duration);}catch{}}
$('sound').onclick=()=>{sound=!sound;$('sound').textContent='Sound: '+(sound?'on':'off');$('sound').setAttribute('aria-pressed',sound);if(sound)tone(660,.15);};
function setRound(n){round=n;['step1','step2','step3'].forEach((id,i)=>$(id).classList.toggle('active',i===n-1));$('roundLabel').textContent=['ROUND 01 / THE SICKNESS SPIN','ROUND 02 / SICK-LEAVE SHOWDOWN','ROUND 03 / RETURN-TO-WORK'][n-1];}
function escapeText(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<45;i++){const el=document.createElement('i');el.className='confetti';el.style.left=Math.random()*100+'%';el.style.background=colours[i%4];el.style.animationDelay=Math.random()*.5+'s';$('confetti').append(el);setTimeout(()=>el.remove(),3500);}}
async function spin(){if(busy||round!==1)return{error:'A round is already in progress.'};busy=true;$('spin').disabled=true;$('spin').textContent='HR IS CHOOSING YOUR DESTINY…';$('wheelCaption').textContent='Please enjoy this compulsory moment of suspense.';const random=new Uint32Array(1);crypto.getRandomValues(random);const index=random[0]%conditions.length;const step=Math.PI*2/conditions.length;const normal=((angle%(Math.PI*2))+Math.PI*2)%(Math.PI*2);const target=(Math.PI*2-(index+.5)*step)%(Math.PI*2);const delta=5*Math.PI*2+((target-normal+Math.PI*2)%(Math.PI*2));const start=angle,duration=matchMedia('(prefers-reduced-motion: reduce)').matches?100:3900;let last=-1;await new Promise(resolve=>{const t0=performance.now();function frame(t){const p=Math.min(1,(t-t0)/duration);angle=start+delta*(1-Math.pow(1-p,4));draw();const tick=Math.floor(angle/step);if(tick!==last){tone(300+tick%5*50);last=tick;}if(p<1)requestAnimationFrame(frame);else resolve();}requestAnimationFrame(frame);});selected=conditions[index];busy=false;points=100;$('score').textContent=points+' PTS';$('spin').textContent='SCENARIO SELECTED';$('wheelCaption').textContent='Your prize: '+selected.name+'. Your actual opponent: paperwork.';setRound(2);showLeave();celebrate();tone(880,.25);return{condition:selected.name,round:'sick_leave',points};}
$('spin').onclick=spin;
function showLeave(){$('content').innerHTML=`<div class="prize"><span class="label">YOUR SCENARIO · +100 POINTS</span><h2>${selected.name}</h2><p>${selected.note}</p></div><form id="leaveForm"><h2>Call it in.</h2><label for="name">Fictional contestant name</label><input id="name" name="name" maxlength="40" required placeholder="e.g. Pat Pending" autocomplete="off"><div class="row"><div><label for="department">Department</label><select id="department" name="department"><option>Spreadsheet Circus</option><option>IT: Have You Restarted?</option><option>Meeting Multiplication</option><option>Strategic Inaction</option><option>Facilities &amp; Firefighting</option><option>The S.L.U.T. Team</option></select></div><div><label for="days">Game days absent</label><select id="days" name="days"><option value="1">1 day</option><option value="2">2 days</option><option value="3">3 days</option><option value="5">5 days</option></select></div></div><label for="notify">How did you notify the office?</label><select id="notify" name="notify"><option>Called the designated manager</option><option>Submitted a ticket to the ticket portal</option><option>Sent a carrier pigeon with a case number</option><option>Attended a meeting about not attending</option></select><label class="check"><input type="checkbox" required><span>I understand this is a pretend form in a comedy game.</span></label><button class="form-button" type="submit">LOCK IN MY SICK-LEAVE FORM</button><p class="help">No real names or health details. Nothing is sent or saved.</p></form>`;$('leaveForm').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const data=new FormData(form);record={name:data.get('name').trim(),department:data.get('department'),days:Number(data.get('days')),notify:data.get('notify')};if(!record.name){$('name').setCustomValidity('Enter a fictional contestant name.');$('name').reportValidity();$('name').oninput=()=>{$('name').setCustomValidity('');};return;}points+=250;$('score').textContent=points+' PTS';setRound(3);showReturn();tone(660,.2);};}
function showReturn(){$('content').innerHTML=`<span class="ticket">SICK LEAVE LOGGED · +250 POINTS</span><h2>Welcome back,<br>${escapeText(record.name)}.</h2><p>Your inbox survived. It has reproduced.</p><form id="returnForm"><label for="fitness">In this fictional scenario, are you ready to return?</label><select id="fitness" required><option value="">Choose your game answer</option><option value="yes">Yes, ready to return</option><option value="support">Ready with some support</option><option value="no">Not ready yet</option></select><label for="support">What would help?</label><select id="support"><option>A manageable workload</option><option>A flexible return</option><option>A quieter workspace</option><option>A proper conversation with my manager</option><option>Fewer meetings about having fewer meetings</option></select><label for="manager">The manager’s opening line</label><select id="manager"><option>“How are you feeling, and what would help?”</option><option>“Can you remember your portal password?”</option><option>“We’ve booked a meeting about this meeting.”</option><option>“The spreadsheet missed you terribly.”</option></select><label class="check"><input type="checkbox" required><span>I confirm that returning requires yet another form.</span></label><button type="submit" class="form-button">FINAL ANSWER: COMPLETE THE ROUND</button></form>`;$('returnForm').onsubmit=e=>{e.preventDefault();if(!e.currentTarget.reportValidity())return;record.fitness=$('fitness').value;record.support=$('support').value;record.manager=$('manager').value;points+=400;finish();};}
function finish(){$('score').textContent=points+' PTS';$('step3').classList.remove('active');$('spin').disabled=false;$('spin').textContent='PLAY ANOTHER ROUND';$('spin').onclick=reset;$('content').innerHTML=`<div class="result"><span class="ticket">THE GRAND FINALE</span><h2>Congratulations!<br>You survived the forms.</h2><div class="points">${points}</div><b>BUREAUCRACY POINTS</b><div class="seal">CERTIFIED PAPERWORK CHAMPION</div><blockquote>“Your prize is a commemorative lanyard and an invitation to the next wellbeing webinar.”</blockquote><div class="summary"><p><b>Contestant:</b> ${escapeText(record.name)}</p><p><b>Scenario:</b> ${selected.name} · ${record.days} game day${record.days===1?'':'s'}</p><p><b>Department:</b> ${escapeText(record.department)}</p><p><b>Return:</b> ${record.fitness==='no'?'Paused — wellbeing comes first.':record.fitness==='support'?'Support requested.':'Ready in this fictional scenario.'}</p><p><b>Forms conquered:</b> 2 · Real submissions: 0</p></div><button id="again" class="form-button">TAKE ANOTHER SPIN</button></div>`;$('again').onclick=reset;celebrate();[523,659,784,1046].forEach((f,i)=>setTimeout(()=>tone(f,.2),i*130));$('wheelCaption').textContent='Illnesses are not a competition. Paperwork, apparently, is.';}
const intro=$('content').innerHTML;
function reset(){gameNumber++;points=0;selected=null;record={};setRound(1);$('score').textContent='0 PTS';$('spin').disabled=false;$('spin').textContent='SPIN TO WIN';$('spin').onclick=spin;$('wheelCaption').textContent='Eight conditions. One aggressively cheerful HR department.';$('content').innerHTML=intro.replace('#0001','#'+String(gameNumber).padStart(4,'0'));}
draw();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'spin_illness_wheel',title:'Spin illness wheel',description:'Start a fictional game round and select an illness scenario. Does not submit a real form.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||Object.keys(input).length)throw new Error('No input fields are accepted.');return spin();}})).catch(()=>{});}catch{}}
